def topological_sort(graph, num_nodes):
    indegree = [0] * num_nodes
    for u in graph:
        for v in graph[u]:
            indegree[v] += 1

    queue = [i for i in range(num_nodes) if indegree[i] == 0]
    order = []

    while queue:
        u = queue.pop(0)
        order.append(u)
        for v in graph[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if len(order) == num_nodes:
        return order
    return []  # Zyklus erkannt!
